local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Wenn du mit der Maus über die QT-Schaltfläche auf der Weltkarte fährst, zeigt die Legende auch den VIP-Stern und das Entwicklerzahnrad mit den passenden QT-Logos."},["title"]="Kartenlegende"}},["version"]="9.0.6",["welcome"]="Die Kartenlegende erklärt jetzt auch die VIP- und Entwicklersymbole."},["esES"]={["sections"]={{["items"]={"Al pasar el cursor sobre el botón de QT en el mapa del mundo, la leyenda muestra la estrella de VIP y el engranaje del desarrollador junto a sus respectivos logotipos de QT."},["title"]="Leyenda del mapa"}},["version"]="9.0.6",["welcome"]="La leyenda del mapa ya incluye los iconos de VIP y del desarrollador."},["esMX"]={["sections"]={{["items"]={"Coloca el cursor sobre el botón de QT en el mapa del mundo: la leyenda incluye la estrella de VIP y el engranaje del desarrollador, cada uno con su logotipo de QT."},["title"]="Leyenda del mapa"}},["version"]="9.0.6",["welcome"]="Ahora puedes identificar los iconos de VIP y del desarrollador en la leyenda del mapa."},["frFR"]={["sections"]={{["items"]={"Survolez le bouton QT de la carte du monde pour retrouver dans la légende l’étoile VIP et la roue dentée du développeur, accompagnées de leurs logos QT respectifs."},["title"]="Légende de la carte"}},["version"]="9.0.6",["welcome"]="Les icônes VIP et développeur figurent désormais dans la légende de la carte."},["itIT"]={["sections"]={{["items"]={"Passando il mouse sul pulsante QT della mappa del mondo, la legenda mostra anche la stella VIP e l’ingranaggio dello sviluppatore, affiancati dai rispettivi loghi QT."},["title"]="Legenda della mappa"}},["version"]="9.0.6",["welcome"]="La legenda della mappa ora include le icone VIP e dello sviluppatore."},["koKR"]={["sections"]={{["items"]={"세계 지도에서 QT 버튼에 마우스를 올리면 VIP 별과 개발자 톱니바퀴 아이콘을 범례에서 확인할 수 있습니다. 각 아이콘 옆에는 해당 QT 로고도 함께 표시됩니다."},["title"]="지도 범례"}},["version"]="9.0.6",["welcome"]="지도 범례에 VIP와 개발자 아이콘 설명이 추가되었습니다."},["ptBR"]={["sections"]={{["items"]={"Passe o cursor sobre o botão do QT no mapa-múndi para ver a estrela de VIP e a engrenagem do desenvolvedor na legenda, acompanhadas dos respectivos logotipos do QT."},["title"]="Legenda do mapa"}},["version"]="9.0.6",["welcome"]="Os ícones de VIP e do desenvolvedor agora estão na legenda do mapa."},["ruRU"]={["sections"]={{["items"]={"Наведите указатель на кнопку QT на карте мира: в легенде теперь есть звезда VIP и шестерёнка разработчика, а рядом с ними — соответствующие логотипы QT."},["title"]="Легенда карты"}},["version"]="9.0.6",["welcome"]="В легенде карты появились пояснения к значкам VIP и разработчика."},["zhCN"]={["sections"]={{["items"]={"将鼠标悬停在世界地图的 QT 按钮上，即可在图例中查看 VIP 星形图标和开发者齿轮图标，以及各自对应的 QT 标志。"},["title"]="地图图例"}},["version"]="9.0.6",["welcome"]="地图图例现在也会说明 VIP 和开发者图标。"},["zhTW"]={["sections"]={{["items"]={"將滑鼠移到世界地圖的 QT 按鈕上，即可在圖例中看到 VIP 星星與開發者齒輪圖示，旁邊也會顯示各自對應的 QT 標誌。"},["title"]="地圖圖例"}},["version"]="9.0.6",["welcome"]="地圖圖例現在也有 VIP 與開發者圖示的說明。"}}
